dart_main:
import 'dart:io';
import 'package:microphone_dart/microphone_dart.dart';
Future<void> main() async {
  final backend = Microphone.backend;
  if (backend.name != 'ffi') throw StateError('native backend did not load');
  await backend.initialize();
  final expected = File(Platform.environment['MICROPHONE_LIB']!).resolveSymbolicLinksSync();
  final mappings = File('/proc/self/maps').readAsLinesSync().where((line) => line.contains('libmicrophone.so')).toList();
  if (mappings.isEmpty || mappings.any((line) => !line.endsWith(' $expected'))) throw StateError('unexpected native mapping: $mappings');
  if (!await backend.hasPermission()) throw StateError('Linux permission unexpectedly denied');
  await Microphone.reset();
  print('Exact native library loaded; recorder initialization, permission query and disposal passed without capture');
}
